import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const source = path.join(
  root,
  'worker',
  'node_modules',
  '@fontsource',
  'noto-sans',
  'files',
  'noto-sans-latin-ext-400-normal.woff2',
);
const target = path.join(root, 'worker', 'noto-sans-latin-ext.mjs');
const bytes = await readFile(source);
const base64 = bytes.toString('base64');
const lines = base64.match(/.{1,100}/g) || [];
const moduleSource = [
  '// Generated by scripts/build-worker-font-module.mjs from @fontsource/noto-sans.',
  '// Noto Sans is licensed under the SIL Open Font License 1.1.',
  'export default [',
  ...lines.map((line) => `  '${line}',`),
  "].join('');",
  '',
].join('\n');
await writeFile(target, moduleSource, 'utf8');
console.log(`Generated ${path.relative(root, target)} (${bytes.length} font bytes).`);
